mapper.update:
UPDATE product SET status = 'onsale', publish_time = sysdate()
WHERE product_id = #{productId}
AND tenant_id = #{tenantId}

UPDATE product SET status = 'rejected', audit_reject_reason = #{reason}
WHERE product_id = #{productId}
AND tenant_id = #{tenantId}

UPDATE sys_user SET status = #{status}, update_time = NOW()
WHERE user_id = #{userId} AND del_flag = '0'
AND tenant_id = #{tenantId}

mapper.select:
SELECT f.flow_id, f.order_id, f.type, f.amount, f.channel, f.third_trans_no, f.create_time
FROM trade_pay_flow f

    JOIN trade_order o ON o.order_id = f.order_id AND o.tenant_id = #{tenantId}

ORDER BY f.create_time DESC
LIMIT #{limit}
